js='''const tl=gsap.timeline({paused:true});window.__timelines={'mochi-v9':tl};const scenes=SCENES;scenes.forEach((s,i)=>{const q='#s'+i,t=s.start;tl.set(q,{visibility:'visible',opacity:1},t);tl.fromTo(q+' .shell',{y:22,scale:.985,opacity:0},{y:0,scale:1,opacity:1,duration:.65,ease:'power3.out'},t);tl.fromTo(q+' .heading',{y:20,opacity:0},{y:0,opacity:1,duration:.6,ease:'power2.out'},t+.15);tl.fromTo(q+' .prompt',{x:34,opacity:0},{x:0,opacity:1,duration:.55,ease:'power2.out'},t+.5);tl.fromTo(q+' .stage',{opacity:0,y:18},{opacity:1,y:0,duration:.5},t+1);const els=gsap.utils.toArray(q+' .step');els.forEach((el,j)=>tl.fromTo(el,{opacity:0,y:18},{opacity:1,y:0,duration:.55,ease:'power2.out'},t+1.5+j*Math.min(.58,4/Math.max(1,els.length))));tl.fromTo(q+' .caption',{opacity:0,y:12},{opacity:1,y:0,duration:.5},t+.8);const hit=document.querySelector(q+' .stage button');let tx=2000,ty=840;if(hit){const r=hit.getBoundingClientRect(),base=document.querySelector(q+' .shell').getBoundingClientRect();tx=r.x-base.x+r.width*.65;ty=r.y-base.y+r.height*.55;}tl.set(q+' .cursor',{left:0,top:0,right:'auto',bottom:'auto'},t);tl.set(q+' .ring',{left:tx-35,top:ty-35,right:'auto',bottom:'auto'},t);tl.fromTo(q+' .cursor',{x:tx-180,y:ty+70,opacity:0},{x:tx,y:ty,opacity:hit?1:0,duration:1.2,ease:'power2.inOut'},t+4);tl.to(q+' .cursor',{scale:.84,duration:.1},t+5.2);tl.to(q+' .cursor',{scale:1,duration:.25},t+5.3);tl.fromTo(q+' .ring',{opacity:hit?.7:0,scale:.25},{opacity:0,scale:1.35,duration:.8},t+5.2);tl.to(q+' .cursor',{opacity:0,duration:.5},t+6.1);tl.fromTo(q+' .progress i',{scaleX:0},{scaleX:1,duration:3.5,ease:'power2.inOut'},t+2.3);tl.fromTo(q+' .bar',{scaleY:0},{scaleY:1,duration:2.2,stagger:.25,ease:'power3.out'},t+2.5);gsap.utils.toArray(q+' .wave i').forEach((el,j)=>tl.fromTo(el,{scaleY:.25},{scaleY:.5+.5*Math.sin(j*1.7)**2,duration:.35+(j%5)*.08,yoyo:true,repeat:12,ease:'sine.inOut'},t+1.4));tl.fromTo(q+' .scan',{y:0},{y:340,duration:3,ease:'none'},t+2);tl.to(q+' .functionline',{attr:{d:'M0 615L760 -525'},duration:3,ease:'power2.inOut'},t+4);tl.to(q+' .slider:first-of-type em',{x:310,duration:3,ease:'power2.inOut'},t+4);tl.fromTo(q+' .pet g',{scaleY:1},{scaleY:.12,transformOrigin:'50% 50%',duration:.13,yoyo:true,repeat:1},t+7.6);tl.to(q,{opacity:0,duration:.35},t+10.65);tl.set(q,{visibility:'hidden'},t+11)});tl.fromTo('.global-progress',{scaleX:0},{scaleX:1,duration:286,ease:'none'},0);tl.to({x:0},{x:1,duration:286,ease:'none'},0);window.seekFilm=t=>tl.seek(t);'''.replace('SCENES',json.dumps(S,ensure_ascii=False))
